// COI Poliza Builder
try {
  const item = $input.item.json;
  const source = item.erp_source;
  const payload = item.payload_json || {};
  const folio = item.folio || '';
  const erpId = item.erp_id;

  const mappingResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${$env.SUPABASE_URL}/rest/v1/coi_account_mapping?select=key,value,label&order=key`,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`
    }
  });
  const mapping = {};
  for (const row of mappingResp) { mapping[row.key] = row.value; }

  function calcIvaSubtotal(total) {
    const subtotal = Math.round((total / 1.16) * 100) / 100;
    const iva = Math.round((total - subtotal) * 100) / 100;
    return { subtotal, iva };
  }

  function getConcepto(p) { return `${p.cliente || 'N/A'} - ${p.folio || folio}`; }

  let poliza = { tipo_poliza: 'DIARIO', movimientos: [] };

  if (source === 'venta') {
    const { subtotal, iva } = calcIvaSubtotal(payload.total || 0);
    poliza.tipo_poliza = 'INGRESO';
    poliza.concepto = getConcepto(payload);
    poliza.movimientos = [
      { num_cuenta: mapping['ventas_cargo'] || '400-01', concepto_mov: 'Venta ' + folio, cargo: 0, abono: subtotal },
      { num_cuenta: mapping['ventas_iva'] || '208-01', concepto_mov: 'IVA venta ' + folio, cargo: 0, abono: iva },
      { num_cuenta: mapping['ventas_abono'] || '110-01', concepto_mov: 'Cobro venta ' + folio, cargo: payload.total || 0, abono: 0 }
    ];
  } else if (source === 'compra') {
    const { subtotal, iva } = calcIvaSubtotal(payload.total || 0);
    poliza.tipo_poliza = 'EGRESO';
    poliza.concepto = `Compra - ${payload.proveedor || 'N/A'} - ${folio}`;
    poliza.movimientos = [
      { num_cuenta: mapping['compras_abono'] || '110-01', concepto_mov: 'Pago compra ' + folio, cargo: 0, abono: payload.total || 0 },
      { num_cuenta: mapping['compras_cargo'] || '600-01', concepto_mov: 'Compra ' + folio, cargo: subtotal, abono: 0 },
      { num_cuenta: mapping['compras_iva'] || '118-01', concepto_mov: 'IVA compra ' + folio, cargo: iva, abono: 0 }
    ];
  } else if (source === 'factura') {
    poliza.tipo_poliza = 'DIARIO';
    poliza.concepto = `Factura - ${folio}`;
    const { subtotal, iva } = calcIvaSubtotal(payload.total || 0);
    poliza.movimientos = [
      { num_cuenta: mapping['factura_cargo'] || '110-01', concepto_mov: 'Factura ' + folio, cargo: payload.total || 0, abono: 0 },
      { num_cuenta: mapping['factura_abono'] || '400-01', concepto_mov: 'Ingreso factura ' + folio, cargo: 0, abono: subtotal },
      { num_cuenta: mapping['factura_iva'] || '208-01', concepto_mov: 'IVA factura ' + folio, cargo: 0, abono: iva }
    ];
  } else if (source === 'nomina') {
    poliza.tipo_poliza = 'EGRESO';
    poliza.concepto = `Nómina - ${folio}`;
    poliza.movimientos = [
      { num_cuenta: mapping['nomina_cargo'] || '510-01', concepto_mov: 'Nómina ' + folio, cargo: payload.total || 0, abono: 0 },
      { num_cuenta: mapping['nomina_abono'] || '110-01', concepto_mov: 'Pago nómina ' + folio, cargo: 0, abono: payload.total || 0 }
    ];
  } else if (source === 'bancos') {
    poliza.tipo_poliza = 'DIARIO';
    poliza.concepto = `Movimiento bancario - ${folio}`;
    const tipo = payload.tipo || 'ingreso';
    poliza.movimientos = [
      { num_cuenta: mapping['bancos_cargo'] || '110-01', concepto_mov: 'Banco ' + folio, cargo: tipo === 'ingreso' ? (payload.monto || 0) : 0, abono: tipo === 'egreso' ? (payload.monto || 0) : 0 }
    ];
  }

  return [{ json: { poliza, source, erpId, folio, queueItemId: item.id, _success: true } }];
} catch (err) {
  const item = $input.item.json;
  return [{ json: { _success: false, errorMessage: err.message, source: item.erp_source, erpId: item.erp_id, folio: item.folio || '', queueItemId: item.id } }];
}

